import pytest

from bedrock_protocol import v975, v1001, v2168

# generated by gophertunnel b8bd735:
# &packet.PartyDestinationCookieResponse{Cookie: "party-cookie", Accepted: true}
ACCEPTED = bytes.fromhex("0c70617274792d636f6f6b696501")

# generated by gophertunnel b8bd735:
# &packet.PartyDestinationCookieResponse{Cookie: "", Accepted: false}
DECLINED = bytes.fromhex("0000")

# generated by gophertunnel b8bd735:
# &packet.PartyDestinationCookieResponse{Cookie: strings.Repeat("c", 200), Accepted: true}
ACCEPTED_LONG_COOKIE = bytes.fromhex(
    "c801636363636363636363636363636363636363636363636363636363636363636363636363636363636363636363636363"
    "6363636363636363636363636363636363636363636363636363636363636363636363636363636363636363636363636363"
    "6363636363636363636363636363636363636363636363636363636363636363636363636363636363636363636363636363"
    "6363636363636363636363636363636363636363636363636363636363636363636363636363636363636363636363636363"
    "636301"
)

GOLDENS = [
    pytest.param(
        v2168.PartyDestinationCookieResponsePacket(cookie="party-cookie", accepted=True),
        ACCEPTED,
        id="accepted",
    ),
    pytest.param(
        v2168.PartyDestinationCookieResponsePacket(cookie="", accepted=False),
        DECLINED,
        id="declined-with-an-empty-cookie",
    ),
    pytest.param(
        v2168.PartyDestinationCookieResponsePacket(cookie="c" * 200, accepted=True),
        ACCEPTED_LONG_COOKIE,
        id="accepted-with-a-varint-length-prefix",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_party_destination_cookie_response_is_packet_350(version):
    assert version.PACKETS[350] is version.PartyDestinationCookieResponsePacket


def test_packet_350_is_not_in_v975():
    assert 350 not in v975.PACKETS


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_party_destination_cookie_response_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_party_destination_cookie_response_decodes_from_its_golden(packet, golden):
    assert v2168.PartyDestinationCookieResponsePacket.from_bytes(golden) == packet
